import { describe, it, expect, vi, beforeEach } from 'vitest';
import { SnippetService, toSnippetRelativePath } from '../snippets/snippet-service';

// ---------------------------------------------------------------------------
// Mock vault harness (kept local — mirrors snippet-service.test.ts pattern).
